// /sbs distances are in mm; convert to m to plot next to the KF state (/pose_topic).
import { Input } from "./types";

type Output = { distance_1: number; distance_2: number; distance_3: number };

export const inputs = ["/sbs"];
export const output = "/studio_script/sbs_m";

export default function script(event: Input<"/sbs">): Output {
  const m = event.message;
  return {
    distance_1: m.distance_1 / 1000,
    distance_2: m.distance_2 / 1000,
    distance_3: m.distance_3 / 1000,
  };
}

sim-kf-error.sourceCode:
// SIM ONLY. KF estimate minus ground truth, both in the pool (world) frame.
// Truth arrives at 20 Hz and the KF at up to 100 Hz, so each KF sample is compared with
// the latest truth: up to 50 ms old, i.e. ~5 mm at 0.1 m/s.
import { Input } from "./types";

type Output = { x: number; y: number; z: number; dist: number };

export const inputs = ["/kf/pool_pose", "/pose_topic_gt"];
export const output = "/studio_script/kf_error";

let truth: { x: number; y: number; z: number } | undefined;

export default function script(
  event: Input<"/kf/pool_pose"> | Input<"/pose_topic_gt">,
): Output | undefined {
  if (event.topic === "/pose_topic_gt") {
    const p = (event as Input<"/pose_topic_gt">).message.pose.pose.position;
    truth = { x: p.x, y: p.y, z: p.z };
    return undefined;
  }
  if (!truth) {
    return undefined;
  }
  const p = (event as Input<"/kf/pool_pose">).message.pose.position;
  const e = { x: p.x - truth.x, y: p.y - truth.y, z: p.z - truth.z };
  return { ...e, dist: Math.hypot(e.x, e.y, e.z) };
}

sim-gt-path.sourceCode:
// SIM ONLY. Ground-truth trail (green) in the world frame for the 3D panel.
import { Input, Message } from "./types";

type Output = Message<"foxglove.PosesInFrame">;

export const inputs = ["/pose_topic_gt"];
export const output = "/studio_script/gt_path";

const MAX_POSES = 20000;
let poses: Output["poses"] = [];
let lastNs = -1;

export default function script(event: Input<"/pose_topic_gt">): Output {
  const t = event.receiveTime;
  const ns = t.sec * 1e9 + t.nsec;
  if (ns < lastNs) {
    poses = []; // seeked backwards: restart the trail
  }
  lastNs = ns;
  const p = event.message.pose.pose.position;
  poses.push({ position: { x: p.x, y: p.y, z: p.z }, orientation: { x: 0, y: 0, z: 0, w: 1 } });
  if (poses.length > MAX_POSES) {
    poses.shift();
  }
  return { timestamp: t, frame_id: "world", poses: poses.slice() };
}

